<?php $id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.active=1");require __DIR__.'/includes/header.php';$st->execute([$id]);$p=$st->fetch();if(!$p){http_response_code(404);echo '<section class="pagehead"><h1>Produk tidak ditemukan</h1></section>';require __DIR__.'/includes/footer.php';exit;} ?><section class="detail"><img src="<?=e(img($p['image']))?>"><div><small><?=e($p['category_name'])?></small><h1><?=e($p['name'])?></h1><?php if($p['description']):?><p><?=nl2br(e($p['description']))?></p><?php endif;if($p['price']!==''):?><h3><?=e($p['price'])?></h3><?php endif;?><a class="btn btn-dark" href="<?=e(wa('Halo Animo Label, saya tertarik dengan produk '.$p['name']))?>">Konsultasi Produk</a></div></section><?php require __DIR__.'/includes/footer.php';?>